// PuddleDuck live-view snapshot helpers.
//
// The WebGL renderer returns pixels bottom-to-top. The helpers below turn
// those pixels into normal top-to-bottom RGBA data for preview/canvas use and
// encode a 32-bit BITMAPV5 image with an alpha channel. The BMP writer emits
// a classic bottom-up bitmap (positive height with rows stored bottom-to-top)
// for better compatibility with embedded readers such as the FrSky X20.
// Transparent pixels retain white RGB values so viewers that ignore BMP alpha
// still display a useful white background rather than black.

export const DUCK_SNAPSHOT_WIDTH = 300;
export const DUCK_SNAPSHOT_HEIGHT = 280;
export const DUCK_SNAPSHOT_DEFAULT_PRESET_ID = 'frsky';
export const DUCK_SNAPSHOT_MIN_DIMENSION = 16;
export const DUCK_SNAPSHOT_MAX_DIMENSION = 2048;
export const DUCK_SNAPSHOT_MAX_PIXELS = DUCK_SNAPSHOT_MAX_DIMENSION ** 2;

export const DUCK_SNAPSHOT_PRESETS = Object.freeze([
  Object.freeze({ id: 'frsky', group: 'Device', label: 'FrSky', width: 300, height: 280, icon: false }),
  Object.freeze({ id: 'favicon-16', group: 'Browser', label: 'Favicon', width: 16, height: 16, icon: true }),
  Object.freeze({ id: 'favicon-32', group: 'Browser', label: 'Favicon', width: 32, height: 32, icon: true }),
  Object.freeze({ id: 'android-48', group: 'Android', label: 'Android mdpi', width: 48, height: 48, icon: true }),
  Object.freeze({ id: 'icon-64', group: 'General icons', label: 'Icon', width: 64, height: 64, icon: true }),
  Object.freeze({ id: 'android-72', group: 'Android', label: 'Android hdpi', width: 72, height: 72, icon: true }),
  Object.freeze({ id: 'android-96', group: 'Android', label: 'Android xhdpi', width: 96, height: 96, icon: true }),
  Object.freeze({ id: 'icon-128', group: 'General icons', label: 'Icon', width: 128, height: 128, icon: true }),
  Object.freeze({ id: 'android-144', group: 'Android', label: 'Android xxhdpi', width: 144, height: 144, icon: true }),
  Object.freeze({ id: 'apple-180', group: 'Apple', label: 'Apple touch', width: 180, height: 180, icon: true }),
  Object.freeze({ id: 'pwa-192', group: 'Web app', label: 'PWA', width: 192, height: 192, icon: true }),
  Object.freeze({ id: 'icon-256', group: 'General icons', label: 'Icon', width: 256, height: 256, icon: true }),
  Object.freeze({ id: 'pwa-384', group: 'Web app', label: 'PWA', width: 384, height: 384, icon: true }),
  Object.freeze({ id: 'pwa-512', group: 'Web app', label: 'PWA', width: 512, height: 512, icon: true }),
  Object.freeze({ id: 'source-1024', group: 'Source artwork', label: 'Source icon', width: 1024, height: 1024, icon: true }),
]);

function _checkedDimension(value, label) {
  const result = Number(value);
  if (!Number.isInteger(result) || result <= 0 || result > 16384) {
    throw new RangeError(`${label} must be a positive integer no larger than 16384`);
  }
  return result;
}

function _checkedSnapshotDimension(value, label) {
  const result = _checkedDimension(value, label);
  if (result < DUCK_SNAPSHOT_MIN_DIMENSION || result > DUCK_SNAPSHOT_MAX_DIMENSION) {
    throw new RangeError(
      `${label} must be an integer from ${DUCK_SNAPSHOT_MIN_DIMENSION} to ${DUCK_SNAPSHOT_MAX_DIMENSION}`,
    );
  }
  return result;
}

export function validateDuckSnapshotDimensions(width, height) {
  const w = _checkedSnapshotDimension(width, 'width');
  const h = _checkedSnapshotDimension(height, 'height');
  if (w * h > DUCK_SNAPSHOT_MAX_PIXELS) {
    throw new RangeError(
      `snapshot area must not exceed ${DUCK_SNAPSHOT_MAX_PIXELS.toLocaleString('en-US')} pixels`,
    );
  }
  return { width: w, height: h };
}

export function duckSnapshotPresetById(presetId) {
  const id = String(presetId || '').trim().toLowerCase();
  return DUCK_SNAPSHOT_PRESETS.find((preset) => preset.id === id) || null;
}

export function duckSnapshotPresetForDimensions(width, height) {
  const { width: w, height: h } = validateDuckSnapshotDimensions(width, height);
  return DUCK_SNAPSHOT_PRESETS.find(
    (preset) => preset.width === w && preset.height === h,
  ) || null;
}

export function flipWebGlRgba(rawPixels, width, height) {
  const w = _checkedDimension(width, 'width');
  const h = _checkedDimension(height, 'height');
  if (!rawPixels || rawPixels.length !== w * h * 4) {
    throw new RangeError(`expected ${w * h * 4} RGBA bytes`);
  }

  const output = new Uint8ClampedArray(rawPixels.length);
  const rowBytes = w * 4;
  for (let y = 0; y < h; y += 1) {
    const srcRow = (h - 1 - y) * rowBytes;
    const dstRow = y * rowBytes;
    for (let x = 0; x < w; x += 1) {
      const src = srcRow + x * 4;
      const dst = dstRow + x * 4;
      const alpha = Number(rawPixels[src + 3]);
      let red = Number(rawPixels[src]);
      let green = Number(rawPixels[src + 1]);
      let blue = Number(rawPixels[src + 2]);

      // Three.js uses premultiplied alpha by default. Convert the edge pixels
      // back to straight alpha before they are written into ImageData/BMP.
      if (alpha === 0) {
        red = 255;
        green = 255;
        blue = 255;
      } else if (alpha < 255) {
        const scale = 255 / alpha;
        red = Math.min(255, Math.round(red * scale));
        green = Math.min(255, Math.round(green * scale));
        blue = Math.min(255, Math.round(blue * scale));
      }

      output[dst] = red;
      output[dst + 1] = green;
      output[dst + 2] = blue;
      output[dst + 3] = alpha;
    }
  }
  return output;
}

export function encodeBmpV5(rgbaPixels, width, height) {
  const w = _checkedDimension(width, 'width');
  const h = _checkedDimension(height, 'height');
  if (!rgbaPixels || rgbaPixels.length !== w * h * 4) {
    throw new RangeError(`expected ${w * h * 4} RGBA bytes`);
  }

  const fileHeaderSize = 14;
  const dibHeaderSize = 124; // BITMAPV5HEADER
  const pixelOffset = fileHeaderSize + dibHeaderSize;
  const imageSize = w * h * 4;
  const fileSize = pixelOffset + imageSize;
  const buffer = new ArrayBuffer(fileSize);
  const view = new DataView(buffer);
  const bytes = new Uint8Array(buffer);

  // BITMAPFILEHEADER
  bytes[0] = 0x42; // B
  bytes[1] = 0x4d; // M
  view.setUint32(2, fileSize, true);
  view.setUint32(10, pixelOffset, true);

  // BITMAPV5HEADER. Use a positive height and write rows bottom-to-top for
  // compatibility with simple BMP readers that assume classic bottom-up data.
  const dib = fileHeaderSize;
  view.setUint32(dib + 0, dibHeaderSize, true);
  view.setInt32(dib + 4, w, true);
  view.setInt32(dib + 8, h, true);
  view.setUint16(dib + 12, 1, true); // planes
  view.setUint16(dib + 14, 32, true); // bits per pixel
  view.setUint32(dib + 16, 3, true); // BI_BITFIELDS
  view.setUint32(dib + 20, imageSize, true);
  view.setInt32(dib + 24, 2835, true); // 72 DPI
  view.setInt32(dib + 28, 2835, true);
  view.setUint32(dib + 40, 0x00ff0000, true); // red mask
  view.setUint32(dib + 44, 0x0000ff00, true); // green mask
  view.setUint32(dib + 48, 0x000000ff, true); // blue mask
  view.setUint32(dib + 52, 0xff000000, true); // alpha mask
  view.setUint32(dib + 56, 0x73524742, true); // LCS_sRGB
  view.setUint32(dib + 108, 4, true); // LCS_GM_IMAGES

  // BMP stores 32-bit pixels in BGRA byte order. Because the bitmap is
  // bottom-up, write the last RGBA row first.
  const rowBytes = w * 4;
  let dst = pixelOffset;
  for (let y = h - 1; y >= 0; y -= 1) {
    const row = y * rowBytes;
    for (let x = 0; x < rowBytes; x += 4) {
      const src = row + x;
      bytes[dst] = rgbaPixels[src + 2];
      bytes[dst + 1] = rgbaPixels[src + 1];
      bytes[dst + 2] = rgbaPixels[src];
      bytes[dst + 3] = rgbaPixels[src + 3];
      dst += 4;
    }
  }

  return bytes;
}

function _safeFilenamePart(value, fallback = 'Duck') {
  return String(value || fallback)
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^A-Za-z0-9._-]+/g, '-')
    .replace(/^-+|-+$/g, '') || fallback;
}

export function duckSnapshotIconFilename(label, size, extension = 'png') {
  const px = _checkedSnapshotDimension(size, 'icon size');
  const duck = _safeFilenamePart(label, 'duck').toLowerCase();
  const ext = String(extension || 'png').toLowerCase() === 'bmp' ? 'bmp' : 'png';
  const generic = new Set(['auto', 'duck', 'puddleduck', 'robot']).has(duck);
  return `${generic ? 'puddleduck' : `puddleduck-${duck}`}-icon-${px}.${ext}`;
}

export function duckSnapshotFilename(label, extension, now = new Date()) {
  const safeLabel = _safeFilenamePart(label, 'Duck');
  const ext = String(extension || 'png').toLowerCase() === 'bmp' ? 'bmp' : 'png';
  const stamp = now.toISOString()
    .replace(/[-:]/g, '')
    .replace(/\.\d{3}Z$/, 'Z')
    .replace('T', '-');
  return `${safeLabel}-${stamp}.${ext}`;
}
